BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "Loan" (
	"Loan_ID"	TEXT,
	"loan_status"	TEXT,
	"Principal"	INTEGER,
	"terms"	INTEGER,
	"effective_date"	TEXT,
	"due_date"	TEXT,
	"paid_off_time"	TEXT,
	"past_due_days"	TEXT,
	"age"	INTEGER,
	"education"	TEXT,
	"Gender"	TEXT
);
COMMIT;
-- =====================
-- LOAN DATA ANALYSIS
-- =====================

-- 1. Total Loans
SELECT COUNT(*) as Total_Loans FROM Loan;

-- 2. Loan Status Breakdown
SELECT loan_status, COUNT(*) as Count
FROM Loan GROUP BY loan_status;

-- 3. Gender Analysis
SELECT Gender, COUNT(*) as Total
FROM Loan GROUP BY Gender;

-- 4. Education vs Avg Loan
SELECT education, ROUND(AVG(Principal), 2) as Avg_Loan
FROM Loan GROUP BY education;

-- 5. Default by Terms
SELECT terms, COUNT(*) as Defaults
FROM Loan WHERE loan_status = 'COLLECTION'
GROUP BY terms;

-- 6. Age Groups
SELECT 
CASE 
  WHEN age < 25 THEN 'Under 25'
  WHEN age BETWEEN 25 AND 35 THEN '25-35'
  WHEN age BETWEEN 36 AND 45 THEN '36-45'
  ELSE 'Above 45'
END as Age_Group,
COUNT(*) as Total_Loans
FROM Loan GROUP BY Age_Group;

-- 7. Default Rate %
SELECT ROUND(COUNT(CASE WHEN loan_status='COLLECTION' 
THEN 1 END) * 100.0 / COUNT(*), 2) as Default_Rate
FROM Loan;

-- 8. Gender + Status
SELECT Gender, loan_status, COUNT(*) as Count
FROM Loan GROUP BY Gender, loan_status;

-- 9. Avg Age Analysis
SELECT 
ROUND(AVG(CASE WHEN loan_status='COLLECTION' THEN age END), 1) as Avg_Age_Defaulters,
ROUND(AVG(CASE WHEN loan_status='PAIDOFF' THEN age END), 1) as Avg_Age_PaidOff
FROM Loan;